from typing import List

from ...base.client import BaseClient


class SuggestsMethods(BaseClient):
    """
    Методы группы 'Саджесты' из https://im-docs.corp.mail.ru/
    """

    async def rapi_getSuggests(self, sn: str, suggestTypes: List[dict]) -> dict:
        """
        Получение саджестов отдельным запросом
        :param sn: идентификатор диалога. Может быть уином, почтой или id чата
        :param suggestTypes: типы саджестов
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/getSuggests",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"sn": sn, "suggestTypes": suggestTypes},
            },
        )

    async def rapi_getSmartReply(self, sn: str, suggestTypes: List[str], msgId: int) -> dict:
        """
        Получение 'умных' ответов
        :param sn: идентификатор диалога. Может быть уином, почтой или id чата
        :param suggestTypes: типы саджестов
        :param msgId: идентификатор сообщения,
        на которое хотим получить smart reply
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/getSmartReply",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "sn": sn,
                    "suggestTypes": suggestTypes,
                    "msgId": msgId,
                },
            },
        )
